 'use strict';
(()=>{
 const C=window.CharacterCampaign,K=window.CharacterData,D=window.GameData,copy=x=>JSON.parse(JSON.stringify(x));
 class Session{
  constructor(result){if(!result?.practice||!C.validBattleRecord(result.practice))throw Error('이전 교전은 시작 조건이 기록되지 않아 연습할 수 없습니다.');this.reference=copy(result);this.record=copy(result.practice);this.pool=copy(this.record.pool);this.ids=[...this.record.deck];this.policy=this.record.config.autoPolicy;this.formationVersion=this.record.config.formationVersion??1;this.formation=this.record.config.formation?[...this.record.config.formation]:null;this.basics=false;this.battle=null;this.results=[];this.reported=false;}
  editable(){return !this.battle||this.battle.s.ended;}
  useBasics(value){if(!this.editable())return false;this.historical=false;this.deckOrigin=null;this.basics=!!value;this.pool=copy(this.record.pool);this.ids=[...this.record.deck];if(this.basics){for(const c of K.basicPool(this.record.config.party)){if(this.pool.filter(x=>x.key===c.key).length>=D.cards[c.key].limit)continue;let serial=0,id;do{id='practice:basic:'+c.key+':'+serial++;}while(this.pool.some(x=>x.id===id));this.pool.push({...c,id});}}return true;}
  canHistorical(list){return Array.isArray(list)&&list.length===20&&C.validBattleRecord({...this.record,pool:list,deck:list.map(c=>c.id)});}
  useStarting(){if(!this.useHistorical(this.startingDeck))return false;this.deckOrigin='starting';this.formation=this.record.config.formation?[...this.record.config.formation]:null;this.formationVersion=this.record.config.formationVersion??1;return true;}
  usePreset(id){if(!this.editable())return false;const preset=id==='starter'?{template:K.starter}:K.startingDecks.find(p=>p.id===id);if(!preset)return false;let chosen=window.TrialCharacter&&this.record.config.party?.some(p=>p.characterId==='ria')?window.TrialCharacter.template(preset.template,'ria'):preset.template;if(window.SupportContent?.template&&this.record.config.party?.some(p=>p.characterId==='noa'))chosen=window.SupportContent.template(chosen,'noa');const base=K.templatePool(chosen),cards=base.ids.map((key,i)=>({...copy(base.pool.find(c=>c.id===key)),id:'practice:preset:'+i}));if(!this.canHistorical(cards))return false;this.pool=cards;this.ids=cards.map(c=>c.id);this.basics=false;this.historical=false;this.deckOrigin='preset';this.presetId=id;return true;}
  useHistorical(list){if(!this.editable()||!this.canHistorical(list))return false;this.pool=copy(list);this.ids=list.map(c=>c.id);this.basics=false;this.historical=true;this.deckOrigin=null;this.policy=this.record.config.autoPolicy;return true;}
  setFormation(value,version=this.formationVersion){if(!this.editable()||!window.Formation.valid(value,version))return false;this.formation=[...value];this.formationVersion=version;return true;}
  compareFormation(){if(!this.editable())return false;this.deploymentComparison=window.DeploymentStudy.compare(this.record,this.formation,this.formationVersion);return true;}
  toggle(id){if(!this.editable()||!this.pool.some(c=>c.id===id))return false;this.deckOrigin=null;const index=this.ids.indexOf(id);if(index<0)this.ids.push(id);else this.ids.splice(index,1);return true;}
  start(){if(!this.editable())return false;const error=D.validateDeck(this.ids,this.pool);if(error)throw Error(error);if(!['attack','protect','balanced'].includes(this.policy))throw Error('오토 방침을 확인하세요.');const config={...copy(this.record.config),control:'auto',autoPolicy:this.policy,targetingRulesVersion:this.record.config.targetingRulesVersion??0,formationVersion:this.formationVersion,formation:this.formation?[...this.formation]:null,cards:this.ids.map(id=>copy(this.pool.find(c=>c.id===id)))};this.current={version:1,engineVersion:1,config:{...config},pool:copy(this.pool),deck:[...this.ids]};delete this.current.config.cards;this.battle=new window.CharacterBattle(config);this.reported=false;return true;}
  step(dt){if(this.battle){this.battle.step(dt);this.observe();}}
  observe(){if(!this.battle?.s.ended||this.reported)return false;this.reported=true;const result=C.summarizeBattle(this.battle,this.current);result.expandedBasics=this.basics;result.historicalDeck=!!this.historical;result.startingDeck=this.deckOrigin==='starting';if(this.deckOrigin==='preset')result.presetId=this.presetId;this.results.unshift(result);this.results=this.results.slice(0,6);return true;}
  pause(){if(!this.battle||this.battle.s.ended)return false;this.battle.s.paused=!this.battle.s.paused;this.battle.s.pauseReason=this.battle.s.paused?'spectator':'';return true;}
 }
 window.BattlePractice={Session};
})();
